import sqlite3, hashlib, json

class EmbedCache:
    def __init__(self, path={{db_path}}):
        self.db = sqlite3.connect(path)
        self.db.execute("CREATE TABLE IF NOT EXISTS emb(k TEXT PRIMARY KEY, v BLOB)")
    def get(self, text):
        k = hashlib.sha256(f"{{{model}}}|{text}".encode()).hexdigest()
        row = self.db.execute("SELECT v FROM emb WHERE k=?", (k,)).fetchone()
        if row: return json.loads(row[0])
        v = {{embed_fn}}(text)
        self.db.execute("INSERT INTO emb VALUES(?,?)", (k, json.dumps(v)))
        self.db.commit()
        return v
